def calc(expr):
    pos = 0
    n = len(expr)

    def skip():
        nonlocal pos
        while pos < n and expr[pos].isspace():
            pos += 1

    def parse_expr():
        nonlocal pos
        value = parse_term()
        while True:
            skip()
            if pos < n and expr[pos] in '+-':
                op = expr[pos]
                pos += 1
                rhs = parse_term()
                if op == '+':
                    value += rhs
                else:
                    value -= rhs
            else:
                break
        return value

    def parse_term():
        nonlocal pos
        value = parse_factor()
        while True:
            skip()
            if pos < n and expr[pos] in '*/':
                op = expr[pos]
                pos += 1
                rhs = parse_factor()
                if op == '*':
                    value *= rhs
                else:
                    value /= rhs
            else:
                break
        return value

    def parse_factor():
        nonlocal pos
        skip()
        if pos < n and expr[pos] in '+-':
            sign = 1 if expr[pos] == '+' else -1
            pos += 1
            return sign * parse_factor()
        if pos < n and expr[pos] == '(':
            pos += 1
            val = parse_expr()
            skip()
            if pos < n and expr[pos] == ')':
                pos += 1
            return val
        start = pos
        while pos < n and expr[pos].isdigit():
            pos += 1
        return float(int(expr[start:pos]))

    result = parse_expr()
    skip()
    return float(result)
