    def tokenize(s):
        tokens = []
        i = 0
        while i < len(s):
            if s[i].isspace():
                i += 1
            elif s[i] in "+-*/()":
                tokens.append(s[i])
                i += 1
            elif s[i].isdigit():
                j = i
                while j < len(s) and s[j].isdigit():
                    j += 1
                tokens.append(int(s[i:j]))
                i = j
            else:
                i += 1
        return tokens

    tokens = tokenize(expr)
    pos = 0

    def parse_expression():
        nonlocal pos
        res = parse_term()
        while pos < len(tokens) and tokens[pos] in ('+', '-'):
            op = tokens[pos]
            pos += 1
            right = parse_term()
            if op == '+':
                res += right
            else:
                res -= right
        return res

    def parse_term():
        nonlocal pos
        res = parse_unary()
        while pos < len(tokens) and tokens[pos] in ('*', '/'):
            op = tokens[pos]
            pos += 1
            right = parse_unary()
            if op == '*':
                res *= right
            else:
                res /= right
        return res

    def parse_unary():
        nonlocal pos
        if tokens[pos] == '-':
            pos += 1
            return -parse_unary()
        elif tokens[pos] == '+':
            pos += 1
            return parse_unary()
        else:
            return parse_factor()

    def parse_factor():
        nonlocal pos
        token = tokens[pos]
        if token == '(':
            pos += 1
            res = parse_expression()
            pos += 1  # Skip closing parenthesis
            return res
        else:
            pos += 1
