import heapq

def shortest_paths(graph, source):
    # Identify all unique nodes that appear as keys or as neighbors in the graph
    nodes_in_graph = set(graph.keys())
    for neighbors in graph.values():
        for v, _ in neighbors:
            nodes_in_graph.add(v)

    # Prepare the distances dictionary
    # Include source in all_nodes to ensure the algorithm can start, 
    # even if source is not explicitly in the graph's edges.
    all_nodes = nodes_in_graph | {source}
    distances = {node: float('inf') for node in all_nodes}
    distances[source] = 0

    # Priority queue for Dijkstra's algorithm: (distance, node)
    pq = [(0, source)]

    while pq:
        current_dist, u = heapq.heappop(pq)

        # If we found a longer path in the queue, skip it
        if current_dist > distances[u]:
            continue

        # Explore neighbors of u
        for v, weight in graph.get(u, []):
            new_dist = current_dist + weight
            if new_dist < distances[v]:
                distances[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    # Return only the distances for nodes that "appear anywhere in the graph"
    return {node: distances[node] for node in nodes_in_graph}
```

