import re

def calc(expr):
    # Tokenize the expression into numbers, operators, and parentheses
    tokens = re.findall(r'\d+\.\d+|\d+|[+\-*/()]', expr)
    i = 0

    def parse_expr():
        nonlocal i
        # expression -> term { (+|-) term }
        res = parse_term()
        while i < len(tokens) and tokens[i] in ('+', '-'):
            op = tokens[i]
            i += 1
            right = parse_term()
            if op == '+':
                res += right
            else:
                res -= right
        return res

    def parse_term():
        nonlocal i
        # term -> unary { (*|/) unary }
        res = parse_unary()
        while i < len(tokens) and tokens[i] in ('*', '/'):
            op = tokens[i]
            i += 1
            right = parse_unary()
            if op == '*':
                res *= right
            else:
                res /= right
        return res

    def parse_unary():
        nonlocal i
        # unary -> - unary | primary
        if i < len(tokens) and tokens[i] == '-':
            i += 1
            return -parse_unary()
        return parse_primary()

    def parse_primary():
        nonlocal i
        # primary -> number | ( expression )
        token = tokens[i]
        i += 1
        if token == '(':
            res = parse_expr()
            # Skip the closing parenthesis
            if i < len(tokens) and tokens[i] == ')':
                i += 1
            return res
        else:
            return float(token)

    return float(parse_expr())
