import re

def calc(expr):
    # Tokenize the input string into numbers and operators
    tokens = re.findall(r'\d+|[+\-*/()]', expr)
    pos = 0

    def peek():
        nonlocal pos
        return tokens[pos] if pos < len(tokens) else None

    def consume():
        nonlocal pos
        token = peek()
        pos += 1
        return token

    def parse_expression():
        # Handle addition and subtraction
        node = parse_term()
        while peek() in ('+', '-'):
            op = consume()
            right = parse_term()
            if op == '+':
                node += right
            else:
                node -= right
        return node

    def parse_term():
        # Handle multiplication and division
        node = parse_factor()
        while peek() in ('*', '/'):
            op = consume()
            right = parse_factor()
            if op == '*':
                node *= right
            else:
                node /= right
        return node

    def parse_factor():
        # Handle unary operators (+ and -)
        if peek() == '-':
            consume()
            return -parse_factor()
        if peek() == '+':
            consume()
            return parse_factor()
        return parse_primary()

    def parse_primary():
        # Handle parentheses and numbers
        token = consume()
        if token == '(':
            result = parse_expression()
            consume()  # Consume closing parenthesis ')'
            return result
        return float(token)

    return float(parse_expression())
```

