import heapq

def shortest_paths(graph, source):
    # Identify all unique nodes in the graph (keys and neighbors)
    nodes = set(graph.keys())
    for neighbors in graph.values():
        for neighbor, weight in neighbors:
            nodes.add(neighbor)

    # Initialize distances with infinity
    distances = {node: float('inf') for node in nodes}

    # Distance from source to itself is 0, provided source is part of the graph
    if source in distances:
        distances[source] = 0

    # Priority queue for Dijkstra's algorithm: (distance, node)
    pq = [(0, source)]

    while pq:
        curr_dist, u = heapq.heappop(pq)

        # Skip if we've already found a shorter path to u
        if curr_dist > distances.get(u, float('inf')):
            continue

        # Relax edges from u to neighbors v
        for v, weight in graph.get(u, []):
            distance = curr_dist + weight
            if distance < distances.get(v, float('inf')):
                distances[v] = distance
                heapq.heappush(pq, (distance, v))

    return distances
