def calc(expr: str) -> float:
    # Tokenize
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        ch = expr[i]
        if ch.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(("NUM", int(expr[i:j])))
            i = j
        elif ch in "+-*/()":
            tokens.append((ch, ch))
            i += 1
        elif ch.isspace():
            i += 1
        else:
            raise ValueError(f"Invalid character: {ch!r}")

    tokens.append(("EOF", None))          # sentinel
    pos = 0

    def peek() -> str:
        return tokens[pos][0]

    def consume(expected: str = None):
        nonlocal pos
        tok = tokens[pos]
        if expected and tok[0] != expected:
            raise ValueError(f"Expected {expected}, got {tok[0]}")
        pos += 1
        return tok

    # Grammar:
    # expr   ::= term ((+|-) term)*
    # term   ::= factor ((*|/) factor)*
    # factor ::= (+|-) factor | NUM | '(' expr ')'

    def parse_factor() -> float:
        if peek() == '+':
            consume('+')
            return parse_factor()
        if peek() == '-':
            consume('-')
            return -parse_factor()
        if peek() == 'NUM':
            return float(consume('NUM')[1])
        if peek() == '(':
            consume('(')
            val = parse_expr()
            if peek() != ')':
                raise ValueError("Missing closing parenthesis")
            consume(')')
            return val
        raise ValueError(f"Unexpected token: {peek()}")

    def parse_term() -> float:
        left = parse_factor()
        while peek() in ('*', '/'):
            op = consume()[0]
            right = parse_factor()
            if op == '*':
                left *= right
            else:  # op == '/'
                left /= right
        return left

    def parse_expr() -> float:
        left = parse_term()
        while peek() in ('+', '-'):
            op = consume()[0]
            right = parse_term()
            if op == '+':
                left += right
            else:  # op == '-'
                left -= right
        return left

    result = parse_expr()
    if peek() != 'EOF':
        raise ValueError("Extra characters after valid expression")
    return result
```

