def calc(expr):
    class Parser:
        def __init__(self, s):
            self.s = s
            self.i = 0
            self.n = len(s)

        def skip_spaces(self):
            while self.i < self.n and self.s[self.i] == ' ':
                self.i += 1

        def peek(self):
            self.skip_spaces()
            return self.s[self.i] if self.i < self.n else None

        def consume(self):
            self.skip_spaces()
            if self.i < self.n:
                ch = self.s[self.i]
                self.i += 1
                return ch
            return None

        def parse_expr(self):
            value = self.parse_term()
            while True:
                op = self.peek()
                if op == '+':
                    self.consume()
                    value += self.parse_term()
                elif op == '-':
                    self.consume()
                    value -= self.parse_term()
                else:
                    break
            return value

        def parse_term(self):
            value = self.parse_factor()
            while True:
                op = self.peek()
                if op == '*':
                    self.consume()
                    value *= self.parse_factor()
                elif op == '/':
                    self.consume()
                    value /= self.parse_factor()
                else:
                    break
            return value

        def parse_factor(self):
            op = self.peek()
            if op == '+':
                self.consume()
                return self.parse_factor()
            elif op == '-':
                self.consume()
                return -self.parse_factor()
            else:
                return self.parse_primary()

        def parse_primary(self):
            ch = self.peek()
            if ch == '(':
                self.consume()
                value = self.parse_expr()
                if self.peek() != ')':
                    raise ValueError("Missing closing parenthesis")
                self.consume()
                return value
            else:
                return self.parse_number()

        def parse_number(self):
            self.skip_spaces()
            start = self.i
            while self.i < self.n and self.s[self.i].isdigit():
                self.i += 1
            if start == self.i:
                raise ValueError("Expected number")
            return float(self.s[start:self.i])

    parser = Parser(expr)
    result = parser.parse_expr()
    parser.skip_spaces()
    if parser.peek() is not None:
        raise ValueError("Unexpected characters at end")
    return result
