            if c.isspace():
                i += 1
                continue
            if c.isdigit():
                j = i
                while j < n and s[j].isdigit():
                    j += 1
                num = int(s[i:j])
                tokens.append(('NUM', num))
                i = j
            elif c == '(':
                tokens.append(('LPAREN', '('))
                i += 1
            elif c == ')':
                tokens.append(('RPAREN', ')'))
                i += 1
            elif c == '+':
                tokens.append(('PLUS',))
                i += 1
            elif c == '-':
                tokens.append(('MINUS',))
                i += 1
            elif c == '*':
                tokens.append(('MUL',))
                i += 1
            elif c == '/':
                tokens.append(('DIV',))
                i += 1
            else:
                raise ValueError(f"Invalid character: {c}")
        return tokens

    tokens = tokenize(expr)
    pos = 0
    n = len(tokens)

    def peek():
        return tokens[pos] if pos < n else None

    def consume():
        nonlocal pos
        token = tokens[pos]
        pos += 1
        return token

    # Grammar: Factor -> Number | '(' Expression ')' | '-' Factor
    def parse_factor():
        tok = peek()
        if tok[0] == 'NUM':
            consume()
            return float(tok[1])
        elif tok[0] == 'LPAREN':
            consume()
            val = parse_expression()
            # expect RPAREN
            if peek() is None or peek()[0] != 'RPAREN':
                raise ValueError("Missing closing parenthesis")
            consume()  # consume RPAREN
            return val
        elif tok[0] == 'MINUS':
            consume()
            # unary minus
            return -parse_factor()
        else:
            raise ValueError(f"Unexpected token {tok}")

    # Term handles * and /
    def parse_term():
        value = parse_factor()
        while True:
            tok = peek()
            if tok and tok[0] in ('MUL', 'DIV'):
                op_tok = consume()
                right = parse_factor()
                if op_tok[0] == 'MUL':
                    value *= right
                else:  # DIV
                    value /= right
            else:
                break
        return value

    # Expression handles + and -
    def parse_expression():
        value = parse_term()
        while True:
            tok = peek()
            if tok and tok[0] in ('PLUS', 'MINUS'):
                op_tok = consume()
                right = parse_term()
                if op_tok[0] == 'PLUS':
                    value += right
                else:  # MINUS
                    value -= right
            else:
                break
        return value

    result = parse_expression()
    if pos != n:
        raise ValueError("Extra tokens at end of expression")
    return float(result)
