    # Collect all nodes that appear either as keys or as neighbours
    nodes = set(graph.keys())
    for u in graph:
        for v, _ in graph[u]:
            nodes.add(v)

    # Initialize distances to infinity
    dist = {node: float('inf') for node in nodes}

    # Set distance of source if it is part of the graph
    if source in dist:
        dist[source] = 0

    # Dijkstra's algorithm using a min-heap
    heap = [(0, source)]
    while heap:
        d, u = heapq.heappop(heap)
        if d != dist[u]:
            continue
        for v, w in graph.get(u, []):
            alt = d + w
            if alt < dist[v]:
                dist[v] = alt
                heapq.heappush(heap, (alt, v))

    return dist
