                num = num * 10 + int(expr[i])
                i += 1
            tokens.append(float(num))
        elif c in '+-*/()':
            # Handle unary minus
            if c == '-':
                # Check if it's unary: at start, or after '(' or after an operator
                if len(tokens) == 0 or tokens[-1] == '(' or (isinstance(tokens[-1], str) and tokens[-1] in '+-*/'):
                    tokens.append('u-')
                else:
                    tokens.append('-')
            else:
                tokens.append(c)
            i += 1
        else:
            raise ValueError(f"Invalid character: {c}")

    # Shunting-yard algorithm to convert to RPN
    output = []
    stack = []
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2, 'u-': 3}
    associativity = {'+': 'left', '-': 'left', '*': 'left', '/': 'left', 'u-': 'right'}

    for token in tokens:
        if isinstance(token, float):
            output.append(token)
        elif token == '(':
            stack.append(token)
        elif token == ')':
            while stack and stack[-1] != '(':
                output.append(stack.pop())
            stack.pop()  # Remove '('
        else:
            # Operator
            while stack and stack[-1] != '(':
                top_op = stack[-1]
                if (precedence[top_op] > precedence[token]) or \
                   (precedence[top_op] == precedence[token] and associativity[token] == 'left'):
                    output.append(stack.pop())
                else:
                    break
            stack.append(token)

    while stack:
        output.append(stack.pop())

    # Evaluate RPN
    eval_stack = []
    for token in output:
        if isinstance(token, float):
            eval_stack.append(token)
        elif token == 'u-':
            a = eval_stack.pop()
            eval_stack.append(-a)
        else:
            b = eval_stack.pop()
            a = eval_stack.pop()
            if token == '+':
                eval_stack.append(a + b)
            elif token == '-':
                eval_stack.append(a - b)
            elif token == '*':
                eval_stack.append(a * b)
            elif token == '/':
                eval_stack.append(a / b)

    return eval_stack[0]
