    def is_operator(token):
        return token in ['+', '-', '*', '/']

    # Recursive descent parser with precedence climbing
    def parse_expression(index):
        return parse_additive(index)

    def parse_additive(index):
        left, index = parse_multiplicative(index)
        while index < len(tokens) and tokens[index] in ['+', '-']:
            op = tokens[index]
            index += 1
            right, index = parse_multiplicative(index)
            if op == '+':
                left = left + right
            else:
                left = left - right
        return left, index

    def parse_multiplicative(index):
        left, index = parse_unary(index)
        while index < len(tokens) and tokens[index] in ['*', '/']:
            op = tokens[index]
            index += 1
            right, index = parse_unary(index)
            if op == '*':
                left = left * right
            else:
                left = left / right
        return left, index

    def parse_unary(index):
        if index < len(tokens) and tokens[index] == '-':
            index += 1
            value, index = parse_unary(index)
            return -value, index
        elif index < len(tokens) and tokens[index] == '+':
            index += 1
            value, index = parse_unary(index)
            return value, index
        return parse_primary(index)

    def parse_primary(index):
        if index >= len(tokens):
            return 0.0, index

        token = tokens[index]
        if token == '(':
            index += 1
            value, index = parse_expression(index)
            if index < len(tokens) and tokens[index] == ')':
                index += 1
            else:
                raise ValueError("Missing closing parenthesis")
            return value, index
        elif isinstance(token, float):
            return token, index + 1
        else:
            raise ValueError(f"Unexpected token: {token}")

    result, _ = parse_expression(0)
    return float(result)
