def calc(expr):
    pos = 0
    n = len(expr)

    def skip():
        nonlocal pos
        while pos < n and expr[pos] == ' ':
            pos += 1

    def peek():
        skip()
        return expr[pos] if pos < n else None

    def advance():
        nonlocal pos
        c = expr[pos]
        pos += 1
        return c

    def parse_expr():
        res = parse_term()
        while peek() in ('+', '-'):
            op = advance()
            right = parse_term()
            res = res + right if op == '+' else res - right
        return res

    def parse_term():
        res = parse_factor()
        while peek() in ('*', '/'):
            op = advance()
            right = parse_factor()
            res = res * right if op == '*' else res / right
        return res

    def parse_factor():
        if peek() == '-':
            advance()
            return -parse_factor()
        if peek() == '+':
            advance()
            return parse_factor()
        if peek() == '(':
            advance()
            res = parse_expr()
            if peek() == ')':
                advance()
            return res
        return parse_number()

    def parse_number():
        nonlocal pos
        start = pos
        while pos < n and expr[pos].isdigit():
            pos += 1
        return float(expr[start:pos])

    return parse_expr()
