import heapq

def shortest_paths(graph, source):
    # 1. Identify all nodes that appear anywhere in the graph (as keys or neighbors)
    nodes = set(graph.keys())
    for neighbors in graph.values():
        for neighbor, weight in neighbors:
            nodes.add(neighbor)

    # 2. Initialize distances for all nodes to infinity
    dist = {node: float('inf') for node in nodes}

    # 3. Initialize Priority Queue for Dijkstra's algorithm
    # We only start from the source if it is actually part of the graph nodes
    if source in dist:
        dist[source] = 0
        pq = [(0, source)]
    else:
        pq = []

    while pq:
        d, u = heapq.heappop(pq)

        # If the popped distance is greater than the current shortest distance, skip
        if d > dist[u]:
            continue

        # Explore neighbors. 'u' might not be a key in 'graph' 
        # if it was only discovered as a neighbor and has no outgoing edges.
        for v, weight in graph.get(u, []):
            new_dist = d + weight
            if new_dist < dist[v]:
                dist[v] = new_dist
                heapq.heappush(pq, (new_dist, v))

    return dist
